import zipfile, xml.etree.ElementTree as ET, re

def dump_xlsx(path, label):
    print(f'=== {label}: {path} ===')
    z = zipfile.ZipFile(path)
    ns = {'s':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
    strings = []
    if 'xl/sharedStrings.xml' in z.namelist():
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall('s:si', ns):
            t = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            strings.append(t)
    sh = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
    for row in sh.findall('.//s:row', ns):
        line = []
        for c in row.findall('s:c', ns):
            ref = c.get('r')
            t = c.get('t')
            v = c.find('s:v', ns)
            val = None
            if t == 's' and v is not None:
                val = strings[int(v.text)]
            elif t == 'inlineStr':
                isn = c.find('s:is', ns)
                val = ''.join(tt.text or '' for tt in isn.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')) if isn is not None else ''
            elif v is not None:
                val = v.text
            if val is not None:
                line.append(f'{ref}={val}')
        if line: print('  ' + ' | '.join(line))
    print()

